python.code:
def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(3))

java.code:
static long factorial(long n) {
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}

javascript.code:
function factorial(n) {
  if (n === 0) {
    return 1;
  }
  return n * factorial(n - 1);
}

console.log(factorial(3));

cpp.code:
long long factorial(long long n) {
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}

python.code:
def sum_list(nums):
    if len(nums) == 0:
        return 0
    return nums[0] + sum_list(nums[1:])

print(sum_list([2, 4, 6]))

java.code:
static long sumList(long[] nums, int index) {
    if (index == nums.length) {
        return 0;
    }
    return nums[index] + sumList(nums, index + 1);
}

javascript.code:
function sumList(nums, index = 0) {
  if (index === nums.length) {
    return 0;
  }
  return nums[index] + sumList(nums, index + 1);
}

console.log(sumList([2, 4, 6]));

cpp.code:
long long sumList(const std::vector<long long>& nums, int index) {
    if (index == (int)nums.size()) {
        return 0;
    }
    return nums[index] + sumList(nums, index + 1);
}

python.code:
def height(node):
    if node is None:
        return 0
    return 1 + max(height(node.left), height(node.right))

java.code:
static int height(Node node) {
    if (node == null) return 0;
    return 1 + Math.max(height(node.left), height(node.right));
}

javascript.code:
function height(node) {
  if (node === null) return 0;
  return 1 + Math.max(height(node.left), height(node.right));
}

cpp.code:
int height(Node* node) {
    if (node == nullptr) return 0;
    return 1 + std::max(height(node->left), height(node->right));
}
